export const WEB_STATIC: Readonly<Record<string, string>> = {
  "app.js": "// ============================================================\n// shell/webui/app.js —— WebUIShell 浏览器应用脚本（三件套之分文件）\n//\n// 结构（批 3 布局）：左栏 = 标题（隠/設）+ 族谱树（状态字前置 + 浮动「選」\n// 菜单）+ 实例化面板 + 快捷设置（模型环/思考程度占位）；主区 = 无边框文档流\n// timeline + composer（输入框在上、信息条行在下：附钮左 · 六项元信息中 ·\n// 状态+连接右 · 送钮右）+ 铺底占用条。header 已废除——agent 事实进信息条，\n// 动作进二级菜单与设置面板（模态，实例/类双页签）。\n// 流式 live 层纪律：delta live-only（applyStreamEvent 分桶），轮末 letter →\n// loadContext 快照收口不补间隙；思维链折叠 running 追最新行、结束定格首行\n// （summary 与 rest 零重复）；rAF 合帧节流。全部纯逻辑住 view.js（可测）。\n// ============================================================\n\nimport { ACT_GLYPH, ROOT_ID, applyStreamEvent, clearBucket, composerMeta, computeTreeRows, contextRatio, createLiveBuckets, deriveActions, infoRows, mdToHtml, menuItems, ratioTone, reasoningView, relativeTime, routeLetters, statusGlyph, statusTone, toolFold, truncate, turnStats } from './view.js'\n\nconst $ = (id) => document.getElementById(id)\nconst timeline = $('timeline')\nlet currentAgentId = ''\nlet agentsCache = []\nlet templatesCache = []\n\n// —— 流式 live 层状态 ——\nconst liveBuckets = createLiveBuckets()\nlet watchAgentId = '' // 监督抽屉目标（'' = 关）\nlet liveHost = null\nlet ctxWindow = 1000000\nlet ctxRatio = 0\nlet paintQueued = false\n\n// ---------- 族谱侧栏 ----------\n\nfunction lanesSvg(row) {\n  const L = 14, half = 12\n  const parts = []\n  const color = row.type === 'node' ? (row.family === 0 ? 'var(--accent)' : row.family === 1 ? 'var(--muted)' : 'var(--border-strong)') : 'var(--border-strong)'\n  for (const lane of row.passThrough ?? []) {\n    parts.push(`<line x1=\"${(lane + 0.5) * L}\" y1=\"0\" x2=\"${(lane + 0.5) * L}\" y2=\"24\" stroke=\"${color}\" stroke-width=\"1\" opacity=\".55\"/>`)\n  }\n  if (row.type === 'node') {\n    const cx = (row.lane + 0.5) * L\n    if (row.join && row.parentLane !== null) {\n      const px = (row.parentLane + 0.5) * L\n      if (px === cx) parts.push(`<line x1=\"${px}\" y1=\"0\" x2=\"${cx}\" y2=\"${half}\" stroke=\"${color}\" stroke-width=\"1\"/>`)\n      else parts.push(`<path d=\"M ${px} 0 L ${px} ${half} L ${cx} ${half}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"1\"/>`)\n    }\n    parts.push(`<circle cx=\"${cx}\" cy=\"${half}\" r=\"3\" fill=\"${row.isRoot ? 'none' : color}\" stroke=\"${color}\" stroke-width=\"1.5\"/>`)\n  } else {\n    parts.push(`<text x=\"${(row.lane + 0.5) * L - 3}\" y=\"15\" fill=\"var(--muted)\" font-size=\"11\">└</text>`)\n  }\n  return `<svg class=\"lanes\" viewBox=\"0 0 ${5 * L} 24\" aria-hidden=\"true\">${parts.join('')}</svg>`\n}\n\nasync function loadAgents(prefetched) {\n  const agents = prefetched ?? await fetch('/api/agents').then((r) => r.json())\n  agentsCache = agents\n  const tree = $('tree')\n  tree.innerHTML = ''\n  for (const row of computeTreeRows(agents)) {\n    const el = document.createElement('div')\n    if (row.type === 'more') {\n      el.className = 'tnode moren'\n      const label = row.kind === 'siblings' ? `… +${row.count} 兄弟（共 ${row.descendants} 实例）` : `… +${row.count} 后代（更深层折叠）`\n      el.innerHTML = lanesSvg(row) + `<span>${label}</span>`\n      tree.appendChild(el)\n      continue\n    }\n    const a = row.row\n    el.className = 'tnode' + (a.id === currentAgentId ? ' active' : '') + (row.isRoot ? ' rootnode' : '')\n    const tone = statusTone(a.status)\n    const glyph = row.isRoot ? ACT_GLYPH.me : statusGlyph(a.status)\n    const lp = a.lastPrompt ? truncate(a.lastPrompt, 24) : `<${a.classRef ?? ''}>`\n    // 状态字前置；「選」钮 CSS 绝对浮动（平时零占位不挤行）\n    el.innerHTML = lanesSvg(row) + `<span class=\"st tone-${tone}\">${glyph}</span><span class=\"id\">${esc(String(a.name ?? a.id))}</span><span class=\"lp\">${esc(decodeEntities(lp))}</span>` +\n      (row.isRoot ? '' : `<span class=\"mbtn\" title=\"操作菜单\">選</span>`)\n    el.onclick = () => selectAgent(a.id)\n    el.oncontextmenu = (e) => { e.preventDefault(); openMenu(a, e.clientX, e.clientY) }\n    const mb = el.querySelector('.mbtn')\n    if (mb !== null) mb.addEventListener('click', (e) => { e.stopPropagation(); const r = mb.getBoundingClientRect(); openMenu(a, r.left - 120, r.bottom + 2) })\n    bindHover(el, a.id)\n    tree.appendChild(el)\n  }\n  renderComposerMeta()\n  renderQuickBox()\n}\n\nconst decodeEntities = (s) => String(s).replace(/&lt;/g, '<').replace(/&gt;/g, '>')\nconst currentAgent = () => agentsCache.find((x) => x.id === currentAgentId) ?? null\n// 呈现面统一 name#id：routeLetters 的发送者标签由它把裸 id 转全名（B4）。\nconst nameOf = (id) => { const a = agentsCache.find((x) => x.id === id); return a !== undefined && a.name !== undefined ? a.name : undefined }\n\n// —— composer 信息条（header 废除后 agent 事实的家）：六项元信息 + 右端状态/连接 ——\nfunction renderComposerMeta() {\n  const a = currentAgent()\n  $('cMeta').innerHTML = a === null ? '<span class=\"item\"><span class=\"k\">族谱全景 · 选择一位后代开始对话</span></span>'\n    : composerMeta(a).map((r, i) => `<span class=\"item${i === 0 ? ' head' : ''}\" title=\"${esc(r.k)}\"><span class=\"k\">${esc(r.k)}</span><span class=\"v\">${esc(r.v)}</span></span>`).join('')\n  const cr = $('cRight')\n  // 注意：重建 cRight 会销毁静态 #conn——读写一律 null-safe（?.），且把连接态\n  // 随重建传递（旧版在此 throw TypeError 截断 selectAgent 后续渲染，事故修复）。\n  const connOn = $('conn')?.classList.contains('on') === true\n  if (a === null) { cr.innerHTML = `<span id=\"conn\" class=\"${connOn ? 'on' : ''}\" title=\"事件流连接\"></span>`; cr.className = '' }\n  else {\n    cr.innerHTML = `<span id=\"agentSt\">${esc(statusGlyph(a.status))} ${esc(String(a.status ?? ''))}</span><span id=\"conn\" class=\"${connOn ? 'on' : ''}\" title=\"事件流连接\"></span>`\n    cr.className = 'tone-' + statusTone(a.status)\n  }\n}\n\n// —— 左栏底：快捷设置（当前 agent 的模型环 + 思考程度占位） ——\nfunction renderQuickBox() {\n  const a = currentAgent()\n  $('quickBox').hidden = a === null\n  if (a === null) return\n  $('quickName').textContent = `${String(a.name ?? a.id)}#${a.id}`\n  renderModelRow(a)\n}\n\nconst ORIGIN_LABEL = { explicit: '显式', class: '类基因', inherited: '父继承', home: '家学' }\nlet modelRefs = []\n\nasync function loadModels() {\n  const data = await fetch('/api/models').then((r) => r.json())\n  modelRefs = data.refs ?? []\n  const cm = $('createModel')\n  cm.innerHTML = ''\n  cm.add(new Option('模型：继承链（类基因>父继承>家学）', ''))\n  for (const ref of modelRefs) cm.add(new Option('出生显式 · ' + ref, ref))\n}\n\nfunction renderModelRow(agent) {\n  const cur = agent === null || agent === undefined ? '' : String(agent.model ?? '')\n  const origin = agent !== null && agent !== undefined ? ORIGIN_LABEL[agent.modelOrigin] ?? agent.modelOrigin ?? '' : ''\n  for (const [sel, badge, inheritLabel] of [[$('modelSel'), $('modelOrigin'), '继承链'], [$('stModel'), $('stModelOrigin'), '继承链']]) {\n    sel.innerHTML = ''\n    if (cur === '') {\n      sel.disabled = true\n      sel.appendChild(new Option('（走继承链）', ''))\n      badge.textContent = inheritLabel\n      continue\n    }\n    sel.disabled = false\n    const refs = modelRefs.includes(cur) ? modelRefs : [cur, ...modelRefs]\n    for (const ref of refs) sel.appendChild(new Option(ref, ref))\n    sel.value = cur\n    badge.textContent = String(origin)\n  }\n}\n\nasync function setModel(ref) {\n  if (!currentAgentId || ref === '') return\n  await fetch('/api/set_model', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: currentAgentId, model: ref }) })\n  await loadAgents()\n}\n$('modelSel').onchange = () => void setModel($('modelSel').value)\n$('stModel').onchange = () => void setModel($('stModel').value)\n\n// —— 悬浮详情卡（infoRows 与数据源同源） ——\nlet hoverTimer = 0\nlet hideTimer = 0\nfunction bindHover(el, id) {\n  el.addEventListener('mouseenter', () => {\n    clearTimeout(hideTimer)\n    hoverTimer = setTimeout(() => {\n      const a = agentsCache.find((x) => x.id === id)\n      if (a === undefined) return\n      const r = el.getBoundingClientRect()\n      const card = $('hoverCard')\n      card.innerHTML = `<div class=\"t\">${esc(String(a.name ?? a.id))}#${esc(a.id)}</div><div class=\"r\">` +\n        infoRows(a).map((row) => `<span>${esc(row.k)}</span><b>${esc(row.v)}</b>`).join('') +\n        `</div><div class=\"r\" style=\"margin-top:3px\"><span>最近对话</span><b>${esc(a.lastPrompt ? truncate(a.lastPrompt, 28) : '—')}</b></div>`\n      card.hidden = false\n      card.style.left = Math.min(r.right + 6, innerWidth - 268) + 'px'\n      card.style.top = Math.min(r.top, innerHeight - card.offsetHeight - 8) + 'px'\n    }, 400)\n  })\n  el.addEventListener('mouseleave', () => {\n    clearTimeout(hoverTimer)\n    hideTimer = setTimeout(() => { $('hoverCard').hidden = true }, 150)\n  })\n  el.addEventListener('mousedown', () => clearTimeout(hoverTimer))\n}\n\n// —— 二级操作菜单（树行「選」/右击；对话/监督/中断/压缩/改名/配置/销毁） ——\nfunction openMenu(agent, x, y) {\n  const m = $('popover')\n  m.innerHTML = ''\n  for (const it of menuItems(agent)) {\n    const b = document.createElement('button')\n    b.textContent = it.label\n    b.dataset.state = it.state\n    if (it.danger === true) b.className = 'danger'\n    if (it.state !== 'off') b.onclick = () => { closeMenu(); void runMenuAction(it.key, agent) }\n    m.appendChild(b)\n  }\n  m.hidden = false\n  m.style.left = Math.min(x, innerWidth - m.offsetWidth - 8) + 'px'\n  m.style.top = Math.min(y, innerHeight - m.offsetHeight - 8) + 'px'\n}\nfunction closeMenu() { $('popover').hidden = true }\ndocument.addEventListener('click', (e) => { const m = $('popover'); if (!m.hidden && !m.contains(e.target)) closeMenu() })\n\nasync function runMenuAction(key, agent) {\n  switch (key) {\n    case 'open': await selectAgent(agent.id); break\n    case 'watch': (watchAgentId === agent.id ? closeDrawer : openDrawer)(agent.id); break\n    case 'interrupt': await fetch('/api/interrupt', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: agent.id }) }); break\n    case 'compact':\n      await fetch('/api/context_action', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: agent.id, action: 'compact' }) })\n      if (agent.id === currentAgentId) await loadContext(agent.id)\n      break\n    case 'rename': await selectAgent(agent.id); openSettings(agent, 'instance'); $('renameInput').focus(); break\n    case 'instanceCfg': openSettings(agent, 'instance'); break\n    case 'classCfg': openSettings(agent, 'class'); break\n    case 'terminate': await terminateAgent(agent); break\n  }\n}\n\n// —— 设置面板（模态双页签：实例参数 + 类定义进化面） ——\nlet settingsAgent = null\nfunction openSettings(agent, tab = 'instance') {\n  settingsAgent = agent\n  $('settingsMask').hidden = false\n  $('stAgent').textContent = `${String(agent.name ?? agent.id)}#${agent.id}`\n  $('renameInput').placeholder = `当前「${String(agent.name ?? agent.id)}」→ 新称呼`\n  $('renameInput').value = ''\n  $('classHint').textContent = ''\n  renderModelRow(currentAgent() ?? agent)\n  fillClassForm(agent.classRef ?? '')\n  switchCfgTab(tab)\n}\nfunction closeSettings() { settingsAgent = null; $('settingsMask').hidden = true }\n$('stClose').onclick = closeSettings\n$('settingsMask').addEventListener('click', (e) => { if (e.target === $('settingsMask')) closeSettings() })\ndocument.addEventListener('keydown', (e) => { if (e.key === 'Escape') { closeSettings(); closeMenu() } })\n$('settingsBtn').onclick = () => openSettings(currentAgent() ?? agentsCache.find((x) => x.id === ROOT_ID) ?? { id: ROOT_ID, name: 'user' })\n\n// 类页签：下拉 = 装载类全集（panel 只读）；字段回填自 templatesCache 现值。\nfunction fillClassForm(classRef) {\n  const sel = $('stClassSel')\n  sel.innerHTML = ''\n  for (const t of templatesCache) sel.appendChild(new Option(t.panel ? `${t.name}（面板·只读）` : t.name, t.name))\n  if (templatesCache.some((t) => t.name === classRef)) sel.value = String(classRef)\n  prefillClass()\n}\nfunction prefillClass() {\n  const t = templatesCache.find((x) => x.name === $('stClassSel').value)\n  const locked = t === undefined || t.panel === true\n  $('stClassDesc').value = t?.description ?? ''\n  $('stClassPrompt').value = t?.systemPrompt ?? ''\n  $('stClassStrategy').value = t?.contextStrategy ?? ''\n  $('stClassTools').textContent = t === undefined ? '' : t.tools === undefined ? '工具：继承父档案' : `工具：${Object.entries(t.tools).map(([k, v]) => `${k}=${v}`).join(' ') || '本地封闭'}`\n  for (const el of [$('stClassDesc'), $('stClassPrompt'), $('stClassStrategy'), $('classSaveBtn')]) el.disabled = locked\n  $('classHint').textContent = t !== undefined && t.panel ? '面板类不可编辑（user/策略 role 红线）' : ''\n}\n$('stClassSel').onchange = prefillClass\n$('classSaveBtn').onclick = async () => {\n  const name = $('stClassSel').value\n  if (name === '') return\n  const r = await fetch('/api/class_update', {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ name, description: $('stClassDesc').value, systemPrompt: $('stClassPrompt').value, contextStrategy: $('stClassStrategy').value }),\n  }).then((x) => x.json())\n  if (r.error !== undefined) { $('classHint').textContent = String(r.error); return }\n  $('classHint').textContent = r.persisted ? '已合并落盘（只影响后续实例）' : '已合并（内存，无落盘通道）'\n  await loadTemplates()\n}\n\nfunction switchCfgTab(tab) {\n  for (const b of $('stTabs').querySelectorAll('button')) b.classList.toggle('on', b.dataset.tab === tab)\n  $('stInstance').hidden = tab !== 'instance'\n  $('stClass').hidden = tab !== 'class'\n}\nfor (const b of $('stTabs').querySelectorAll('button')) b.onclick = () => switchCfgTab(b.dataset.tab)\n\n$('renameBtn').onclick = async () => {\n  const name = $('renameInput').value.trim()\n  if (name === '' || settingsAgent === null) return\n  const r = await fetch('/api/update', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: settingsAgent.id, name }) }).then((x) => x.json())\n  if (r.error !== undefined) { alert(String(r.error)); return }\n  $('renameInput').value = ''\n  await loadAgents()\n}\n\n// ---------- 第一视角时间线 ----------\n\nfunction renderTimeline(items) {\n  timeline.innerHTML = ''\n  liveHost = null // 历史整建：live 尾层随 next paint 重建\n  for (const it of items) {\n    if (it.kind === 'meta') { timeline.appendChild(msgEl('meta', it.icon + '  ' + it.text)); continue }\n    if (it.kind === 'tool') { timeline.appendChild(toolLineEl(it.text, it.who, it.toolName)); continue } // 工具结果 = 默认折叠件\n    timeline.appendChild(msgEl(it.side, it.text, it.who))\n  }\n  if (items.length === 0) timeline.appendChild(emptyHint())\n  timeline.scrollTop = timeline.scrollHeight\n}\n\n/** 工具结果行折叠件：默认收起一行头 = **工具名**（首行）+ 来源 + 规模；展开看全文。 */\nfunction toolLineEl(text, who, toolName) {\n  const el = document.createElement('div')\n  const tf = toolFold(text)\n  el.className = 'toolmsg shut'\n  el.title = '点击展开/收起工具输出'\n  const head = document.createElement('div')\n  head.className = 'thead'\n  // 首行格式：`工`（主色图标）+ 工具名（普通色，关联还原；无则回退结果首行）\n  // + 末尾字数/行数统计。**不显示调用者**——工具行显然属于当前窗 agent，省略噪音。\n  const nameText = toolName ?? (tf === null ? '' : tf.head)\n  const meta = tf === null ? '' : tf.meta\n  head.innerHTML = `<b class=\"ticon\">${ACT_GLYPH.tool}</b><span class=\"tname\">${esc(nameText)}</span> <span class=\"tcnt\">${esc(meta)}</span>`\n  const body = document.createElement('div')\n  body.className = 'tbody'\n  body.textContent = tf === null ? text : tf.full\n  el.appendChild(head)\n  el.appendChild(body)\n  el.onclick = () => el.classList.toggle('shut')\n  return el\n}\n\nfunction emptyHint() {\n  const el = document.createElement('div')\n  el.id = 'empty'\n  if (treeAgentsOf(agentsCache).length === 0) {\n    el.innerHTML = '族谱仅根 <b>user#0</b>。<br/>于左下「<b>生</b>」实例化第一位后代，它将成为你的子节点、开启协作。'\n  } else {\n    el.innerHTML = '从左侧<b>族谱树</b>选择一位后代开始对话。'\n  }\n  return el\n}\n\nfunction msgEl(cls, text, who) {\n  const el = document.createElement('div')\n  el.className = 'msg ' + cls\n  if (who) el.innerHTML = `<div class=\"who\">${esc(who)}</div>`\n  if (cls === 'tool' || cls === 'meta') {\n    el.appendChild(document.createTextNode(text)) // 非 markdown 通道保原样\n  } else {\n    const d = document.createElement('div')\n    d.className = 'md'\n    d.innerHTML = mdToHtml(text)\n    el.appendChild(d)\n    const cp = document.createElement('button') // hover 复制原文\n    cp.className = 'copyBtn'; cp.textContent = '複'; cp.title = '复制原文'\n    cp.onclick = () => { void navigator.clipboard?.writeText(text) }\n    el.appendChild(cp)\n  }\n  return el\n}\n\nasync function loadContext(id) {\n  if (id !== currentAgentId) return // 快速连点防御：迟到响应不覆盖新选窗口\n  const data = await fetch('/api/agents/' + encodeURIComponent(id) + '/context').then((r) => r.json())\n  if (id !== currentAgentId) return\n  ctxWindow = Number(data.contextWindow) > 0 ? Number(data.contextWindow) : 1000000\n  renderTimeline(routeLetters(data.messages || [], id, ROOT_ID, nameOf))\n  ctxRatio = contextRatio(data.messages, ctxWindow)\n  paintCtxBar(ctxRatio)\n  const st = turnStats(data.messages)\n  const ts = $('turnStats')\n  ts.hidden = !(st.durationS > 0)\n  ts.textContent = st.durationS > 0 ? `最近一轮耗时 ${st.durationS.toFixed(1)}s` : '' // 轮数/token 已在信息条\n  schedulePaint()\n}\n\n// ---------- 上下文占用进度条（composer 之下铺底，三色带） ----------\n\nfunction paintCtxBar(ratio) {\n  const fill = $('ctxFill')\n  fill.style.width = Math.round(ratio * 100) + '%'\n  fill.className = ratioTone(ratio)\n  $('ctxBar').title = `上下文占用 ${(ratio * 100).toFixed(1)}% / ${ctxWindow.toLocaleString()} tokens`\n}\n\n// ---------- 流式 live 层渲染（rAF 合帧节流；主列尾与抽屉共用 builder） ----------\n\nfunction liveDom(bucket, id) {\n  const frag = document.createDocumentFragment()\n  const running = bucket.text === '' // 正文未起 = 还在想\n  const rv = reasoningView(bucket.reasoning, running)\n  if (rv !== null) {\n    // 自定义折叠件（弃 native details）：**默认展开流全文**、点击任意处收起/\n    // 展开、收起态只留头行——两态零重复；shut 态记在 bucket 上跨帧存活。\n    const d = document.createElement('div')\n    const shut = bucket.rShut === true\n    d.className = 'reason' + (shut ? ' shut' : '') + (running ? ' running' : '')\n    const head = document.createElement('div')\n    head.className = 'rsum'\n    head.textContent = rv.summary\n    const full = document.createElement('div')\n    full.className = 'rfull'\n    full.innerHTML = mdToHtml(rv.full)\n    d.appendChild(head)\n    d.appendChild(full)\n    d.onclick = () => {\n      bucket.rShut = !(bucket.rShut === true)\n      d.classList.toggle('shut')\n    }\n    frag.appendChild(d)\n  }\n  for (const t of bucket.tools) {\n    const chip = document.createElement('div')\n    const dur = t.doneAt > 0 && t.doneAt >= t.at ? ' · ' + ((t.doneAt - t.at) / 1000).toFixed(1) + 's' : ''\n    chip.className = 'chip ' + t.phase\n    chip.textContent = `${ACT_GLYPH.tool} ${t.name} ${t.phase === 'called' ? '执行' : t.phase === 'success' ? '完成' : '失败'}${dur}`\n    frag.appendChild(chip)\n  }\n  if (bucket.text !== '') {\n    const b = document.createElement('div')\n    b.className = 'msg agent streaming'\n    const who = document.createElement('div'); who.className = 'who'; who.textContent = bucketLabel(id)\n    b.appendChild(who)\n    const d = document.createElement('div')\n    d.className = 'md'\n    d.innerHTML = mdToHtml(bucket.text)\n    b.appendChild(d)\n    frag.appendChild(b)\n  }\n  return frag\n}\n\nconst bucketLabel = (id) => { const a = agentsCache.find((x) => x.id === id); return a !== undefined && a.name !== undefined ? a.name : id }\n\nfunction nearBottom() { return timeline.scrollHeight - timeline.scrollTop - timeline.clientHeight < 160 }\n\nfunction renderLive() {\n  updateSendState() // 桶出现/收口即时反映到送钮（busy 灰条 / 空闲恢复）\n  const b = currentAgentId !== '' ? liveBuckets[currentAgentId] : undefined\n  if (b !== undefined) {\n    if (liveHost === null || !liveHost.isConnected) {\n      liveHost = document.createElement('div')\n      liveHost.id = 'liveHost'\n      timeline.appendChild(liveHost)\n    }\n    const stick = nearBottom()\n    liveHost.replaceChildren(liveDom(b, currentAgentId))\n    if (stick) timeline.scrollTop = timeline.scrollHeight\n  } else if (liveHost !== null) {\n    liveHost.remove()\n    liveHost = null\n  }\n  if (watchAgentId !== '') {\n    const wb = liveBuckets[watchAgentId]\n    if (wb !== undefined) {\n      const body = $('drawerBody')\n      const stick = body.scrollHeight - body.scrollTop - body.clientHeight < 160\n      body.replaceChildren(liveDom(wb, watchAgentId))\n      if (stick) body.scrollTop = body.scrollHeight\n    }\n  }\n}\n\nfunction schedulePaint() {\n  if (paintQueued) return\n  paintQueued = true\n  requestAnimationFrame(() => { paintQueued = false; renderLive() })\n}\n\n// ---------- 监督抽屉 ----------\n\nfunction openDrawer(id) {\n  watchAgentId = id\n  $('drawer').hidden = false\n  $('drawerTitle').textContent = '督 · ' + bucketLabel(id)\n  schedulePaint()\n}\nfunction closeDrawer() {\n  if (watchAgentId !== '') clearBucket(liveBuckets, watchAgentId)\n  watchAgentId = ''\n  $('drawer').hidden = true\n  $('drawerBody').innerHTML = ''\n}\n$('drawerClose').onclick = closeDrawer\n\n// ---------- 事件流（delta + tool 相进桶；letter 快照收口；status 清画布） ----------\n\nfunction openStream() {\n  const es = new EventSource('/api/events')\n  es.onopen = () => {\n    $('conn')?.classList.add('on')\n    // 快照追平：事件流无回放（SSE 断线/服务端重启窗口会丢 status/letter）——\n    // 凡连接建立/重连成功，live 桶与忙态一律作废、以仓库历史为准重建（delta\n    // live-only 纪律的另一半：断帧不补，快照自愈）。\n    for (const id of Object.keys(liveBuckets)) clearBucket(liveBuckets, id)\n    roundBusy = false\n    void loadAgents()\n    if (currentAgentId !== '') void loadContext(currentAgentId)\n    schedulePaint()\n    updateSendState()\n  }\n  es.onmessage = (e) => handleEvent(JSON.parse(e.data))\n  es.onerror = () => { $('conn')?.classList.remove('on'); es.close(); setTimeout(openStream, 2000) }\n}\n\nfunction handleEvent(ev) {\n  applyStreamEvent(liveBuckets, ev)\n  if (ev.type === 'stream' || ev.type === 'tool') {\n    if (ev.agentId === currentAgentId || ev.agentId === watchAgentId) schedulePaint()\n    return\n  }\n  if (ev.type === 'letter') {\n    const content = (ev.letters && ev.letters[0] && typeof ev.letters[0].content === 'string') ? ev.letters[0].content : ''\n    void loadAgents()\n      if (ev.agentId === currentAgentId) {\n        void loadContext(currentAgentId).catch((e) => console.error('[ui] loadContext@letter', e))\n      void loadAgents()\n    }\n    return\n  }\n  if (ev.type === 'status') {\n    void loadAgents()\n    if (ev.agentId === currentAgentId && ev.to === 'thinking') roundBusy = true\n    else if (ev.agentId === currentAgentId && (ev.to === 'holding' || ev.to === 'idle' || ev.to === 'interrupted')) {\n      // 轮末收口三步全部**同步**（快照拉取失败也绝不让光标/灰钮滞留）：\n      // 忙态解除 + 桶清 + 光标退场，然后才尽力刷新历史。\n      roundBusy = false\n      clearBucket(liveBuckets, ev.agentId)\n      schedulePaint()\n      void loadContext(currentAgentId).catch((e) => console.error('[ui] loadContext@holding', e))\n    }\n    if (ev.to === 'thinking') clearBucket(liveBuckets, ev.agentId) // 新轮开画布\n    if (ev.agentId === watchAgentId && (ev.to === 'holding' || ev.to === 'idle')) schedulePaint() // 抽屉定格保留到下轮\n    updateSendState()\n  }\n}\n\n// ---------- 会话动作 ----------\n\nlet sendAllowed = false\nlet roundBusy = false // thinking→holding 之间 = 回复未完整收口，送钮灰防误触\nlet sendInFlight = false\n\nfunction updateSendState() {\n  const busy = sendInFlight || roundBusy || (currentAgentId !== '' && liveBuckets[currentAgentId] !== undefined)\n  const canSend = sendAllowed && !busy\n  $('sendBtn').disabled = !canSend\n  $('input').disabled = !sendAllowed\n  const a = currentAgent()\n  $('input').placeholder = !sendAllowed ? '选择一位后代开始对话…'\n    : busy ? `${String(a?.name ?? a?.id ?? '')} 回复中——本轮收口后可继续（消息会合并投递）`\n    : `向 ${a?.name ?? a?.id ?? ''} 发消息（Enter 发送，Shift+Enter 换行）`\n}\n\nfunction applyActions(agent) {\n  sendAllowed = agent !== null && agent !== undefined && deriveActions(agent).send !== 'off'\n  updateSendState()\n}\n\nasync function selectAgent(id) {\n  currentAgentId = id\n  roundBusy = false // 换窗不复用旧窗的轮忙态（下个 status 事件自然校正）\n  // 即点即清屏：旧窗内容零残留（空态占位），数据两请求**并行**拉取——\n  // 历史窗口渲染不依赖 agents 行集，串行 await 会让远程主机延迟翻倍。\n  timeline.innerHTML = ''\n  timeline.appendChild(emptyHint())\n  sendAllowed = false\n  updateSendState()\n  const agentsP = fetch('/api/agents').then((r) => r.json())\n  const ctxP = fetch('/api/agents/' + encodeURIComponent(id) + '/context').then((r) => r.json())\n  const pair = await Promise.all([agentsP, ctxP]).catch((e) => {\n    console.error('[ui] selectAgent 数据拉取失败', e)\n    return null\n  })\n  if (pair === null) return\n  const [agents, ctx] = pair\n  if (id !== currentAgentId) return // 等待期已切窗：本轮作废\n  agentsCache = agents\n  const a = agents.find((x) => x.id === id) ?? null\n  applyActions(a)\n  renderComposerMeta()\n  renderQuickBox()\n  const msgs = ctx.messages || []\n  renderTimeline(routeLetters(msgs, id, ROOT_ID, nameOf))\n  ctxWindow = Number(ctx.contextWindow) > 0 ? Number(ctx.contextWindow) : 1000000\n  paintCtxBar(contextRatio(msgs, ctxWindow))\n  if (a !== null && a.parentId === null) {\n    $('turnStats').hidden = true // 根箱无\"轮\"语义（扮演接口不跑 LLM 轮）\n  } else {\n    const st = turnStats(msgs)\n    const ts = $('turnStats')\n    ts.hidden = !(st.durationS > 0)\n    ts.textContent = st.durationS > 0 ? `最近一轮耗时 ${st.durationS.toFixed(1)}s` : ''\n  }\n  schedulePaint()\n  void loadAgents(agents) // 树重绘复用同一次拉取（高亮换人）\n}\n\nasync function terminateAgent(agent) {\n  const id = agent.id\n  if (!confirm(`销毁 ${id}？（级联销毁其子树；消息语料保留于仓库）`)) return\n  await fetch('/api/terminate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ agentId: id, recursive: true }) })\n  if (id === currentAgentId) {\n    currentAgentId = ''\n    $('turnStats').hidden = true\n    applyActions(null)\n    timeline.innerHTML = ''; timeline.appendChild(emptyHint())\n  }\n  if (id === watchAgentId) closeDrawer()\n  if (settingsAgent !== null && settingsAgent.id === id) closeSettings()\n  await loadAgents()\n}\n\n// ---------- 侧栏收起 / 展开 ----------\n$('sideToggle').onclick = () => {\n  const mini = document.body.classList.toggle('side-mini')\n  $('sideToggle').textContent = mini ? '展' : '隠'\n  $('sideToggle').title = mini ? '展开侧栏' : '收起侧栏（简化族谱）'\n}\n\n// ---------- 对话与实例化 ----------\n\nasync function send() {\n  const text = $('input').value.trim()\n  if (text === '' || !currentAgentId) return\n  $('input').value = ''\n  sendInFlight = true\n  updateSendState()\n  try {\n    await fetch('/api/send', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ to: currentAgentId, text }) })\n  } finally {\n    sendInFlight = false\n    updateSendState()\n  }\n}\n\nasync function createAgent() {\n  const className = $('createClass').value\n  const userPrompt = $('createPrompt').value.trim() || '你好，请做一个简短的自我介绍。'\n  const body = { className, userPrompt }\n  const model = $('createModel').value // 空 = 不显式（落类基因>父继承>家学链）\n  if (model) body.model = model\n  const name = $('createName').value.trim() // 空 = 派生 类名-N\n  if (name !== '') body.name = name\n  const r = await fetch('/api/instantiate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })\n  const data = await r.json()\n  if (data.error !== undefined) { alert(String(data.error)); return }\n  if (data.agentId) { $('createPrompt').value = ''; $('createName').value = ''; void selectAgent(data.agentId) }\n}\n\nasync function loadTemplates() {\n  const templates = await fetch('/api/templates').then((r) => r.json())\n  templatesCache = templates\n  const sel = $('createClass')\n  sel.innerHTML = ''\n  for (const t of templates) {\n    if (t.panel) continue // 面板类（user/策略 role）不可实例化对话\n    sel.appendChild(new Option(t.name, t.name))\n  }\n}\n\n$('sendBtn').onclick = send\n$('input').addEventListener('keydown', (e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() } })\n$('createBtn').onclick = createAgent\n\nfunction esc(s) { return String(s).replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c])) }\n\n// ---------- 启动（空桌引导） ----------\n;(async () => {\n  await loadModels()\n  await loadTemplates()\n  await loadAgents()\n  await selectAgent(ROOT_ID)\n  openStream()\n})()\n",
  "index.html": "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>stem · WebUIShell</title>\n<link rel=\"stylesheet\" href=\"/style.css\" />\n</head>\n<body>\n<aside>\n  <h1>STEM <small>· 族谱</small><span class=\"ico\" id=\"settingsBtn\" data-state=\"ready\" title=\"设置面板（实例/类配置）\">設</span><span class=\"ico\" id=\"sideToggle\" data-state=\"ready\" title=\"收起侧栏（再点展开）\">隠</span></h1>\n  <div id=\"tree\"></div>\n  <div id=\"createBox\">\n    <h3>实例化后代（user#0 = 根）</h3>\n    <div class=\"qrow\"><label>类</label><select id=\"createClass\" title=\"出生类（工具/策略基因随类）\"></select></div>\n    <div class=\"qrow\"><label>模型</label><select id=\"createModel\" title=\"出生显式模型（模型三环·环一）；缺省 = 类基因>父继承>家学\"></select></div>\n    <div class=\"qrow\"><label>称呼</label><input id=\"createName\" placeholder=\"缺省派生 类名-N（全局唯一）\" /></div>\n    <div class=\"qrow\"><label>提词</label><input id=\"createPrompt\" placeholder=\"首条 user prompt…\" /></div>\n    <button id=\"createBtn\">生 · 实例化</button>\n  </div>\n  <div id=\"quickBox\" hidden>\n    <h3>快捷设置 · <span id=\"quickName\">—</span></h3>\n    <div class=\"qrow\"><label>模型</label><select id=\"modelSel\" title=\"切换运行时模型（下一轮生效，不级联子女）\"></select><span id=\"modelOrigin\" class=\"origin\"></span></div>\n    <div class=\"qrow\"><label>思考程度</label><select id=\"effortSel\" disabled title=\"模型侧推理预算控制（即将上线）\"><option>即将上线</option></select></div>\n  </div>\n</aside>\n<main>\n  <div id=\"timeline\"></div>\n  <div id=\"turnStats\" hidden></div>\n  <div id=\"cBox\">\n    <textarea id=\"input\" placeholder=\"选择一位后代开始对话…\" disabled></textarea>\n    <div id=\"cBar\">\n      <button id=\"attachBtn\" title=\"附件（即将上线）\" data-state=\"off\">附</button>\n      <div id=\"cMeta\"></div>\n      <span id=\"cRight\"><span id=\"agentSt\"></span><span id=\"conn\" title=\"事件流连接\"></span></span>\n      <button id=\"sendBtn\" disabled>送</button>\n    </div>\n  </div>\n  <div id=\"ctxBar\" title=\"上下文窗口占用\"><div id=\"ctxFill\"></div></div>\n</main>\n<div id=\"hoverCard\" hidden></div>\n<div id=\"popover\" hidden></div>\n<div id=\"settingsMask\" hidden>\n  <div id=\"settingsPanel\">\n    <div id=\"stHead\"><span>设置 · <span id=\"stAgent\">—</span></span><span class=\"sp\"></span><span class=\"ico\" id=\"stClose\" title=\"关闭\">閉</span></div>\n    <div id=\"stTabs\">\n      <button data-tab=\"instance\" class=\"on\">实例配置</button>\n      <button data-tab=\"class\">类配置</button>\n    </div>\n    <div id=\"stInstance\" class=\"stPane\">\n      <div class=\"row\"><label>模型</label><select id=\"stModel\" title=\"运行时换模型（下一轮生效，不级联子女）\"></select><span id=\"stModelOrigin\" class=\"origin\"></span></div>\n      <div class=\"row\"><label>思考程度</label><select disabled title=\"模型侧推理预算控制（即将上线）\"><option>即将上线</option></select></div>\n      <div class=\"row\"><input id=\"renameInput\" placeholder=\"新称呼（全局唯一）\" /><button id=\"renameBtn\">改名</button></div>\n      <div class=\"row\"><button data-state=\"off\" title=\"工具收敛清单编辑（后续强化）\">工 · 工具收敛（待强化）</button></div>\n      <div class=\"hint\">此页签写**实例行**参数（运行期）；出生设置见左栏实例化面板。</div>\n    </div>\n    <div id=\"stClass\" class=\"stPane\" hidden>\n      <div class=\"row\"><label>类</label><select id=\"stClassSel\"></select></div>\n      <div class=\"row\"><input id=\"stClassDesc\" placeholder=\"类描述（description）\" /></div>\n      <textarea id=\"stClassPrompt\" rows=\"8\" placeholder=\"系统提示词（systemPrompt）…\"></textarea>\n      <div class=\"row\"><label>策略</label><select id=\"stClassStrategy\"><option value=\"\">继承</option><option value=\"classic\">classic</option><option value=\"none\">none</option><option value=\"cortex\">cortex</option></select><span id=\"stClassTools\" class=\"hint\"></span></div>\n      <div class=\"row\"><button id=\"classSaveBtn\">存 · 更新类定义</button><span id=\"classHint\" class=\"hint\"></span></div>\n      <div class=\"hint\">类更新走宿主进化面（同名合并落盘 .stem/agent/，**只影响后续实例**）；面板/user 类不可编辑。</div>\n    </div>\n  </div>\n</div>\n<div id=\"drawer\" hidden>\n  <div id=\"drawerHead\"><span id=\"drawerTitle\">督</span><span class=\"sp\"></span><span class=\"ico\" id=\"drawerClose\" title=\"关闭监督抽屉\">閉</span></div>\n  <div id=\"drawerBody\"></div>\n</div>\n<div id=\"permission\">\n  <div class=\"title\">审 · 工具访问确认</div>\n  <div class=\"body\" id=\"permBody\"></div>\n  <div class=\"row\">\n    <button class=\"once\" id=\"permOnce\">单次批准</button>\n    <button class=\"always\" id=\"permAlways\">始终批准</button>\n    <button class=\"reject\" id=\"permReject\">拒绝</button>\n  </div>\n</div>\n<script type=\"module\" src=\"/app.js\"></script>\n</body>\n</html>\n",
  "style.css": "/* ============================================================\n * shell/webui/style.css —— WebUIShell 样式（OLED 无边框主题）\n *\n * 设计语言：纯黑底、双色语义（青绿=运行/品红=介入）、消息无边框文档流\n * （opencode 风）、composer 容器化（输入框 + 信息条 + 铺底占用条）、\n * 细滚动条全主题化、禁横向溢出（内容自适应换行）。\n * ============================================================ */\n\n:root {\n  --bg: #000000;            /* OLED 纯黑 */\n  --surface: #060708;       /* 极深面板 */\n  --border: #1c2026;        /* 主分层线 */\n  --border-strong: #2e3540;\n  --text: #eef1f3;\n  --muted: #6b7480;\n  --accent: #3df5c8;        /* 青绿 = 正常/运行/激活 */\n  --accent-dim: rgba(61, 245, 200, .16);\n  --alert: #ff2ec8;         /* 品红 = 需介入（interrupted / 危险） */\n  --alert-dim: rgba(255, 46, 200, .16);\n  --warn: #e8c34a;\n  --lane-w: 14px;\n}\n* { box-sizing: border-box; margin: 0; padding: 0; }\nhtml, body { height: 100%; overflow: hidden; }\nbody { background: var(--bg); color: var(--text); font: 14px/1.55 system-ui, \"PingFang SC\", \"Microsoft YaHei\", sans-serif; display: flex; }\n::selection { background: var(--accent-dim); }\n\n/* —— 滚动条主题适配（opencode 风：细身透明轨、悬停提亮；WebKit + Firefox 双轨） —— */\n::-webkit-scrollbar { width: 10px; height: 10px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb { background: #1a1e24; border-radius: 6px; border: 2px solid transparent; background-clip: padding-box; }\n::-webkit-scrollbar-thumb:hover { background: #2a323c; background-clip: padding-box; }\n* { scrollbar-width: thin; scrollbar-color: #1a1e24 transparent; }\n\nbutton { background: transparent; color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 4px 12px; cursor: pointer; font-size: 12px; }\nbutton:hover { border-color: var(--border-strong); color: var(--accent); }\nbutton[data-state=\"off\"] { color: var(--muted); border-color: transparent; cursor: not-allowed; }\nbutton[data-state=\"off\"]:hover { color: var(--muted); border-color: transparent; }\nselect { background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 4px 6px; font-size: 12px; }\nselect:focus { outline: none; border-color: var(--accent); }\nselect:disabled { color: var(--muted); }\n\n/* 三态动作字（R8） */\n.ico { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px;\n       border: 1px solid var(--border); border-radius: 4px; font-size: 12px; line-height: 1; cursor: pointer; flex: 0 0 auto; }\n.ico[data-state=\"off\"] { color: var(--muted); border-color: transparent; cursor: not-allowed;\n       background: repeating-linear-gradient(45deg, transparent 0 3px, #0d1013 3px 4px); }\n.ico[data-state=\"ready\"] { color: var(--text); border-color: var(--border-strong); }\n.ico[data-state=\"ready\"]:hover { color: var(--accent); border-color: var(--accent); }\n.ico[data-state=\"active\"] { color: var(--accent); border-color: var(--accent); box-shadow: 0 0 8px var(--accent-dim); }\n.ico.danger[data-state=\"ready\"] { color: var(--muted); }\n.ico.danger[data-state=\"ready\"]:hover { color: var(--alert); border-color: var(--alert); }\n\n/* ==================== 左栏：标题+按钮 / 族谱 / 实例化 / 快捷设置 ==================== */\naside { width: 320px; min-width: 320px; background: var(--surface); border-right: 1px solid var(--border); display: flex; flex-direction: column; }\naside h1 { font-size: 14px; letter-spacing: .06em; padding: 12px 14px; border-bottom: 1px solid var(--border); font-weight: 600; display: flex; align-items: center; gap: 8px; }\naside h1 small { color: var(--muted); font-weight: normal; flex: 1; }\n\n#tree { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 6px 0; }\n.tnode { position: relative; display: flex; align-items: center; gap: 6px; padding: 5px 8px 5px 4px; cursor: pointer; border-left: 2px solid transparent; }\n.tnode:hover { background: #090b0d; }\n.tnode.active { border-left-color: var(--accent); background: #090b0d; }\n.tnode .lanes { width: calc(var(--lane-w) * 5); flex: 0 0 auto; height: 24px; }\n.tnode .st { font-size: 11px; font-family: ui-monospace, monospace; flex: 0 0 auto; } /* 状态字前置 */\n.tnode .st.tone-active { color: var(--accent); }\n.tnode .st.tone-alert { color: var(--alert); }\n.tnode .st.tone-ready { color: var(--muted); }\n.tnode .id { font-family: ui-monospace, monospace; font-size: 12px; font-weight: 600; white-space: nowrap; }\n.tnode.active .id { color: var(--accent); }\n.tnode.rootnode .id { color: var(--muted); }\n.tnode .lp { color: var(--muted); font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; min-width: 0; }\n.tnode.moren { color: var(--muted); font-size: 11px; font-family: ui-monospace, monospace; padding: 3px 12px 3px 8px; }\n.tnode.moren .lanes { height: 18px; }\n/* 二级菜单钮：绝对浮动（平时零占位，hover 浮在行上） */\n.mbtn { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); opacity: 0; pointer-events: none;\n        color: var(--muted); font-size: 11px; background: var(--surface); border: 1px solid var(--border); border-radius: 3px; padding: 0 5px; cursor: pointer; transition: opacity .08s; }\n.tnode:hover .mbtn { opacity: 1; pointer-events: auto; }\n.mbtn:hover { color: var(--accent); border-color: var(--accent); }\n\n/* 收起态：只留简化族谱（全名） */\nbody.side-mini aside { width: 150px; min-width: 150px; }\nbody.side-mini #createBox, body.side-mini #quickBox, body.side-mini .tnode .lanes,\nbody.side-mini .tnode .lp, body.side-mini aside h1 small { display: none; }\n\n#createBox { padding: 10px 12px; border-top: 1px solid var(--border); display: flex; flex-direction: column; gap: 6px; }\n#createBox h3, #quickBox h3 { font-size: 11px; color: var(--muted); font-weight: 600; letter-spacing: .08em; }\n#createBox .qrow { display: flex; align-items: center; gap: 8px; }\n#createBox .qrow label { color: var(--muted); font-size: 11px; flex: 0 0 auto; width: 32px; }\n#createBox select, #createBox input { background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 5px 8px; font-size: 12px; flex: 1; min-width: 0; }\n#createBox select:focus, #createBox input:focus { outline: none; border-color: var(--accent); }\n#createBox button { border-color: var(--accent); color: var(--accent); }\n#createBox button:hover { background: var(--accent-dim); }\n\n#quickBox { border-top: 1px solid var(--border); padding: 10px 12px; display: flex; flex-direction: column; gap: 7px; }\n#quickBox[hidden] { display: none; }\n#quickBox .qrow { display: flex; align-items: center; gap: 8px; font-size: 12px; }\n#quickBox .qrow label { color: var(--muted); flex: 0 0 auto; }\n#quickBox select { flex: 1; min-width: 0; color: var(--accent); }\n.origin { color: var(--muted); border: 1px solid var(--border); border-radius: 3px; padding: 0 5px; font-size: 11px; flex: 0 0 auto; }\n.stPane .row label { color: var(--muted); flex: 0 0 auto; font-size: 12px; }\n.stPane .row select { flex: 1; min-width: 0; color: var(--accent); }\n.stPane textarea { background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 6px 8px; font-size: 12px; font-family: ui-monospace, monospace; resize: vertical; width: 100%; }\n.stPane textarea:focus { outline: none; border-color: var(--accent); }\n\n/* ==================== 主区：无边框文档流 ==================== */\nmain { flex: 1; display: flex; flex-direction: column; min-width: 0; }\n#timeline { flex: 1; overflow-y: auto; overflow-x: hidden; padding: 14px 22px 20px; display: flex; flex-direction: column; gap: 10px; }\n\n/* 消息 = 无边框文档流；me 右对齐；一切内容自适应禁横滚 */\n.msg { position: relative; max-width: 86%; min-width: 0; word-break: break-word; overflow-wrap: anywhere; }\n.msg.me { align-self: flex-end; }\n.msg.agent, .msg.them { align-self: flex-start; }\n.msg .who { font-size: 11px; color: var(--muted); margin-bottom: 2px; font-family: ui-monospace, monospace; }\n.msg.me .who { color: var(--accent); text-align: right; }\n.msg.agent .who, .msg.them .who { color: var(--accent); opacity: .85; } /* 发送者全名标签主题色 */\n.msg .md p { margin: 0 0 6px; } .msg .md > :last-child { margin-bottom: 0; }\n.msg .md h1, .msg .md h2, .msg .md h3, .msg .md h4, .msg .md h5, .msg .md h6 { margin: 6px 0 4px; font-size: 1.02em; color: var(--accent); }\n.msg .md pre { background: #0a0d10; border: 1px solid var(--border); border-radius: 4px; padding: 8px 10px; font-size: 12px; margin: 4px 0; white-space: pre-wrap; word-break: break-word; overflow: hidden; } /* 换行自适应，无横向滚动条 */\n.msg .md code { background: #0f1317; border-radius: 3px; padding: 0 4px; font-size: 12px; font-family: ui-monospace, monospace; word-break: break-all; }\n.msg .md pre code { background: none; border: none; padding: 0; word-break: break-word; }\n.msg .md ul, .msg .md ol { margin: 4px 0 6px 18px; } .msg .md li { margin: 1px 0; }\n.msg .md blockquote { border-left: 2px solid var(--muted); color: var(--muted); padding-left: 8px; margin: 4px 0; }\n.msg .md table { border-collapse: collapse; margin: 4px 0; font-size: 12px; table-layout: fixed; width: 100%; } /* 固定布局防撑破 */\n.msg .md th, .msg .md td { border: 1px solid var(--border); padding: 2px 8px; word-break: break-word; overflow: hidden; } .msg .md th { background: #0a0d10; }\n.msg .md a { color: var(--accent); overflow-wrap: anywhere; }\n.msg .md hr { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\n.toolmsg { align-self: stretch; max-width: 100%; font-family: ui-monospace, monospace; font-size: 11px; color: var(--muted);\n            border-left: 2px solid #12151a; padding-left: 8px; cursor: pointer; position: relative; }\n.toolmsg:hover { color: var(--text); }\n.toolmsg .thead { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-right: 20px; }\n.toolmsg .thead::after { content: \"▾\"; position: absolute; right: 4px; color: #3a414b; font-size: 10px; }\n.toolmsg.shut .thead::after { content: \"▸\"; }\n/* 首行：`工` 图标主色 + 工具名普通色 + 末尾统计；不显调用者 */\n.toolmsg .ticon { color: var(--accent); margin-right: 6px; font-weight: 600; }\n.toolmsg .tname { color: var(--text); }\n.toolmsg .tcnt { color: #3a414b; margin-left: 6px; }\n.toolmsg .tbody { display: none; white-space: pre-wrap; word-break: break-word; margin-top: 4px; }\n.toolmsg:not(.shut) .tbody { display: block; }\n.msg.meta { align-self: stretch; text-align: center; font-size: 11px; color: var(--accent); white-space: pre-wrap; border-top: 1px dashed #12332a; border-bottom: 1px dashed #12332a; padding: 3px; }\n.copyBtn { position: absolute; top: 0; right: -26px; width: 22px; height: 18px; padding: 0; font-size: 10px; color: var(--muted); border-color: transparent; }\n.msg:hover .copyBtn { border-color: var(--border); }\n.copyBtn:hover { color: var(--accent); }\n.msg.streaming .md { display: inline; }\n.msg.streaming::after { content: \"\"; display: inline-block; width: 7px; height: 1em; margin-left: 1px; vertical-align: -2px;\n       border-right: 2px solid var(--accent); animation: blink 1s step-end infinite; }\n@keyframes blink { 50% { opacity: 0; } }\n\n#turnStats { padding: 0 22px 2px; font-size: 11px; color: var(--muted); font-family: ui-monospace, monospace; }\n#turnStats[hidden] { display: none; }\n\n#empty { align-self: center; margin: auto; text-align: center; color: var(--muted); font-size: 13px; max-width: 360px; line-height: 1.8; }\n#empty b { color: var(--accent); font-weight: 600; }\n\n/* —— composer（opencode 风容器：输入框在上、信息条行在下、附件左送右） —— */\n#cBox { margin: 0 22px 10px; border: 1px solid var(--border); border-radius: 10px; background: #040506; flex: 0 0 auto; }\n#cBox:focus-within { border-color: var(--border-strong); box-shadow: 0 0 0 1px var(--border-strong); }\n#input { display: block; width: 100%; resize: none; height: 46px; background: transparent; color: var(--text); border: none; padding: 11px 14px 2px; font-size: 14px; font-family: inherit; }\n#input:focus { outline: none; }\n#input:disabled { color: var(--muted); cursor: not-allowed; }\n#cBar { display: flex; align-items: center; gap: 12px; padding: 4px 10px 7px 12px; min-width: 0; }\n#attachBtn { color: var(--muted); border-color: transparent; padding: 2px 8px; font-size: 13px; flex: 0 0 auto; }\n#cMeta { flex: 1; min-width: 0; display: flex; align-items: baseline; gap: 14px; font-size: 11px; font-family: ui-monospace, monospace; color: var(--muted); white-space: nowrap; overflow-x: auto; scrollbar-width: none; }\n#cMeta::-webkit-scrollbar { display: none; }\n#cMeta .item { display: inline-flex; gap: 4px; } #cMeta .k { color: #3a414b; } #cMeta .v { color: var(--text); }\n#cMeta .item.head .v { color: var(--accent); font-weight: 600; }\n#cRight { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 8px; font-size: 11px; font-family: ui-monospace, monospace; color: var(--muted); }\n#cRight.tone-active { color: var(--accent); } #cRight.tone-alert { color: var(--alert); }\n#sendBtn { border-color: var(--accent); color: var(--accent); padding: 3px 18px; font-size: 14px; border-radius: 8px; flex: 0 0 auto; }\n#sendBtn:hover { background: var(--accent-dim); }\n#sendBtn:disabled { border-color: var(--border); color: var(--muted); cursor: not-allowed; background: none; }\n\n/* —— 上下文占用进度条（最底铺满） —— */\n#ctxBar { height: 3px; background: #08090b; flex: 0 0 auto; }\n#ctxFill { height: 100%; width: 0; background: var(--accent); transition: width .35s ease; }\n#ctxFill.warn { background: var(--warn); } #ctxFill.danger { background: var(--alert); }\n\n/* ==================== 流式 live 层 ==================== */\n#liveHost { display: flex; flex-direction: column; gap: 10px; }\n/* 思维链（自定义折叠件）：**默认展开流全文**、点击任意处切换、浅色不斜体无边框，\n   与正文以浅色分隔线相隔；收起态只留头行（running=最新行/完成=首行），两态零重复 */\n.reason { align-self: flex-start; width: 100%; max-width: 86%; color: var(--muted); font-size: 12px;\n          border-bottom: 1px solid var(--border); padding-bottom: 7px; margin-bottom: 9px; cursor: pointer; position: relative; }\n.reason::after { content: \"▾\"; position: absolute; right: 2px; top: 0; color: #3a414b; font-size: 10px; }\n.reason.shut::after { content: \"▸\"; }\n.reason .rsum { display: none; }\n.reason.shut .rsum { display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n.reason.shut .rfull { display: none; }\n.reason.running .rfull::after, .reason.running .rsum::after { content: \" ▍\"; animation: blink 1s step-end infinite; }\n.reason .rfull { word-break: break-word; overflow-wrap: anywhere; } /* md 结构渲染，禁 pre-wrap（否则块级换行叠 margin 出双空行） */\n.reason .rfull p, .reason .rfull ul, .reason .rfull ol, .reason .rfull li { margin: 0 0 2px; } /* 与浅字正文同距 */\n.chip { align-self: flex-start; font-size: 11px; font-family: ui-monospace, monospace; color: var(--muted); border: 1px solid var(--border); border-radius: 10px; padding: 1px 10px; }\n.chip.called { color: var(--accent); box-shadow: 0 0 6px var(--accent-dim); }\n.chip.success { color: var(--accent); }\n.chip.error { color: var(--alert); border-color: var(--alert); }\n\n/* ==================== 悬浮层：详情卡 / 操作菜单 / 设置面板 / 监督抽屉 / 审 ==================== */\n#hoverCard { position: fixed; z-index: 12; width: 260px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 6px; padding: 8px 10px; font-size: 11px; pointer-events: none; box-shadow: 0 4px 18px rgba(0,0,0,.65); }\n#hoverCard[hidden] { display: none; }\n#hoverCard .t { font-family: ui-monospace, monospace; font-weight: 600; margin-bottom: 4px; }\n#hoverCard .r { display: grid; grid-template-columns: auto 1fr; gap: 0 8px; color: var(--muted); }\n#hoverCard .r b { color: var(--text); font-weight: normal; text-align: right; font-family: ui-monospace, monospace; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n#popover { position: fixed; z-index: 13; min-width: 132px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 6px; padding: 4px; display: flex; flex-direction: column; box-shadow: 0 6px 20px rgba(0,0,0,.7); }\n#popover[hidden] { display: none; }\n#popover button { border: none; text-align: left; padding: 5px 10px; border-radius: 4px; font-size: 12px; }\n#popover button:hover { background: #0d1115; }\n#popover button.danger:hover { color: var(--alert); background: var(--alert-dim); }\n\n/* 设置面板（模态：实例配置 / 类配置 双页签——左栏腾出空间后的家） */\n#settingsMask { position: fixed; inset: 0; background: rgba(0,0,0,.62); z-index: 20; display: flex; align-items: center; justify-content: center; }\n#settingsMask[hidden] { display: none; }\n#settingsPanel { width: 520px; max-width: 92vw; max-height: 80vh; overflow-y: auto; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; box-shadow: 0 12px 48px rgba(0,0,0,.8); }\n#stHead { display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 600; }\n#stHead .sp { flex: 1; }\n#stTabs { display: flex; gap: 6px; }\n#stTabs button { padding: 2px 12px; font-size: 12px; color: var(--muted); border-color: transparent; }\n#stTabs button.on { color: var(--accent); border-color: var(--border); }\n.stPane { display: flex; flex-direction: column; gap: 8px; }\n.stPane[hidden] { display: none; }\n.stPane .row { display: flex; gap: 8px; align-items: center; }\n.stPane .row input { flex: 1; min-width: 0; background: var(--bg); color: var(--text); border: 1px solid var(--border); border-radius: 4px; padding: 5px 8px; font-size: 12px; }\n.stPane .row input:focus { outline: none; border-color: var(--accent); }\n#classDef { max-height: 260px; overflow-y: auto; font-size: 12px; font-family: ui-monospace, monospace; color: var(--muted); white-space: pre-wrap; word-break: break-word; background: #040506; border: 1px solid var(--border); border-radius: 4px; padding: 10px; }\n.hint { font-size: 11px; color: var(--muted); }\n\n#drawer { position: fixed; right: 16px; top: 16px; bottom: 16px; width: 380px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: 6px; display: flex; flex-direction: column; z-index: 9; padding: 10px 12px; gap: 8px; overflow: hidden; box-shadow: 0 0 24px rgba(0,0,0,.6); }\n#drawer[hidden] { display: none; }\n#drawerHead { display: flex; align-items: center; gap: 8px; font-size: 12px; font-family: ui-monospace, monospace; color: var(--accent); }\n#drawerHead .sp { flex: 1; }\n#drawerBody { flex: 1; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; gap: 8px; }\n#drawerBody .msg, #drawerBody .reason { max-width: 100%; }\n\n#permission { position: fixed; left: 50%; transform: translateX(-50%); top: 20px; width: 380px; background: var(--surface); border: 1px solid var(--alert); border-radius: 6px; padding: 14px; display: none; z-index: 24; box-shadow: 0 6px 24px rgba(0,0,0,.7); }\n#permission .title { font-weight: 600; margin-bottom: 6px; color: var(--alert); }\n#permission .body { color: var(--muted); font-size: 13px; margin-bottom: 12px; }\n#permission .row { display: flex; gap: 8px; }\n#permission .once { border-color: var(--accent); color: var(--accent); }\n#permission .reject { border-color: var(--alert); color: var(--alert); }\n\n#conn { width: 8px; height: 8px; border-radius: 50%; background: var(--muted); display: inline-block; flex: 0 0 auto; }\n#conn.on { background: var(--accent); box-shadow: 0 0 6px var(--accent-dim); }\n",
  "view.js": "// ============================================================\n// shell/webui/view.js —— WebUI 视图纯函数核心（S6 批 2，R8/R9）\n//\n// 零 DOM（浏览器经 <script type=\"module\"> import；node:test 直测）。\n// 承载八组纯逻辑：\n//   1. 汉字字形表（R8：禁 emoji/几何字符，状态/动作全汉字）+ 三态语义；\n//   2. 信箱归位 routeLetters（R9 第一视角：根非对话窗口，来信按\n//      <sender> 反查归位各 agent 窗）；\n//   3. git 风族谱行序 computeTreeRows（DFS + 泳道 + 溢出折叠）；\n//   4. 按钮可用性 deriveActions（能力数据驱动，非 agent 特判——\n//      根不可销毁等事实全部来自族谱位置，seed #5 就此消除）；\n//   5. 流式 live 桶 reducer applyStreamEvent（delta live-only，快照收口）；\n//   6. 思维链折叠 reasoningView（running 追最新行 / 结束定格首行）；\n//   7. 上下文占用 contextRatio + ratioTone（底部进度条数据层）；\n//   8. 零依赖 markdown 子集渲染 mdToHtml（先抽码后转义 = XSS 构造安全）；\n//   9. 出生路径 id 自然序 idOrder（族谱显式排序）；\n//  10. 二级操作菜单 menuItems / 信息卡 infoRows / 相对时间 relativeTime /\n//      对话尾统计 turnStats（批 3：控件收进菜单、hover 详情、统计条——全数据驱动）。\n// ============================================================\n\n/** 本空间根（pilot 扮演身份的约定 id）。 */\nexport const ROOT_ID = '0'\n\n// ---------- 1. 字形表（R8） ----------\n\n/** 状态字形：静/思/持/断（idle/thinking/holding/interrupted）。 */\nexport const STATUS_GLYPH = {\n  idle: '静',\n  thinking: '思',\n  holding: '持',\n  interrupted: '断',\n}\n\n/** 动作字形：停/缩/毁/生/送/审/工/摘/我/模。 */\nexport const ACT_GLYPH = {\n  interrupt: '停',\n  compact: '缩',\n  terminate: '毁',\n  spawn: '生',\n  send: '送',\n  review: '审',\n  tool: '工',\n  summary: '摘',\n  me: '我',\n  model: '模',\n}\n\nexport const statusGlyph = (status) => STATUS_GLYPH[status] ?? '·'\n\n/** 三态视觉（R8）：off=不可用（遮罩）/ ready=可用（白边框）/ active=激活（荧光）。 */\nexport const statusTone = (status) =>\n  status === 'thinking' || status === 'holding' ? 'active' : status === 'interrupted' ? 'alert' : 'ready'\n\n// ---------- 2. 信箱文本（sender 归位原料） ----------\n\n/** 剥发送者戳：`<sender id=\"name#id\" at=\"yymmdd.hhmm\">…</sender>` → {sender, text}。 */\nexport function stripSender(raw) {\n  const m = /^<sender id=\"([^\"]+)\"(?: at=\"[^\"]*\")?>([\\s\\S]*?)<\\/sender>$/.exec(String(raw ?? ''))\n  if (m) return { sender: m[1] ?? '', text: m[2] ?? '' }\n  return { sender: '', text: String(raw ?? '') }\n}\n\n/** 折叠空白并截断（侧栏行摘要用）。 */\nexport function truncate(text, max = 30) {\n  const flat = String(text ?? '').replace(/\\s+/g, ' ').trim()\n  return flat.length > max ? flat.slice(0, max) + '…' : flat\n}\n\n/**\n * 信箱消息流 → 时间线渲染描述（R9 第一视角核心，纯函数）。\n * item = {kind:'msg'|'tool'|'meta', side:'me'|'agent'|'them', who, text, icon}\n * - 常规 agent 窗：user 信按 sender 归位（我=根来信右侧；他 agent 来信左侧）；\n * - 根（user#0）窗：反相——assistant = 人类发言（右\"我\"），user = 后代回信（左）；\n * - system 不上线；invalid（compact 归档）跳过；tag=summary 出中缝元条。\n */\nexport function routeLetters(messages, currentId, rootId = ROOT_ID, nameOf) {\n  const atRoot = currentId === rootId\n  const items = []\n  // 预扫：assistant.toolCalls[].id → 工具名（工具结果行据此还原首行工具名）。\n  const toolNameById = new Map()\n  for (const m of messages ?? []) {\n    const tcs = m?.toolCalls ?? []\n    for (const tc of tcs) {\n      if (tc !== undefined && tc.id !== undefined && tc.name !== undefined) toolNameById.set(String(tc.id), String(tc.name))\n    }\n  }\n  for (const m of messages ?? []) {\n    if (!m.valid) continue\n    if (m.tag === 'summary') { items.push({ kind: 'meta', icon: ACT_GLYPH.summary, text: '上下文摘要（compact 归档，原文保留可审计）' }); continue }\n    const role = m.role\n    if (role === 'system') continue\n    if (role === 'tool') {\n      // 工具结果行：who = 当前 agent 全名（来源）；toolName = 关联的调用名\n      //（assistant.toolCalls.id 映射）——首行显工具名，展开看具体内容（用户裁决）。\n      const who = nameOf && nameOf(currentId) ? `${String(nameOf(currentId))}#${currentId}` : currentId\n      const toolName = toolNameById.get(m?.toolCallId !== undefined ? String(m.toolCallId) : '')\n      items.push({ kind: 'tool', icon: ACT_GLYPH.tool, who, toolName, text: String(m.content ?? '') })\n      continue\n    }\n    if (role === 'user') {\n      const { sender, text } = stripSender(m.content)\n      if (atRoot) {\n        // 根窗（呈现面=你）：人类发言（assistant 行）在右；后代回信（user 行）一律在左——标准聊天惯例。\n        items.push({ kind: 'msg', side: 'them', who: sender ? `来自 ${sender}` : '来信', text })\n      } else {\n        // agent 窗（呈现面=该 agent）：**它自己的回复在左，收到的一切消息（根/其它 agent）在右**——\n        // 右侧统一对齐（含邮局合并投递的多封），who 仍区分来源（我=根，来自 xxx=它人）。\n        const fromRoot = sender === '' || sender === rootId || sender.endsWith('#' + rootId)\n        const who = fromRoot ? ACT_GLYPH.me : `来自 ${sender}`\n        items.push({ kind: 'msg', side: 'me', who, text })\n      }\n      continue\n    }\n    if (role === 'assistant') {\n      // 纯 tool-call 轮（正文为空）跳过——无源文本仅漂浮名字误导；工具意图\n      // 由紧随的工具结果行承接（who 已标）。有正文的正常渲染全名标签。\n      if (String(m.content ?? '').trim() === '') continue\n      const who = atRoot ? ACT_GLYPH.me : nameOf && nameOf(currentId) ? `${String(nameOf(currentId))}#${currentId}` : currentId\n      items.push({ kind: 'msg', side: atRoot ? 'me' : 'agent', who, text: String(m.content ?? '') })\n    }\n  }\n  return items\n}\n\n// ---------- 3. git 风族谱行序（DFS + 泳道 + 折叠） ----------\n\n/** 家族分支色板（OLED 低饱和，仅两种主色交替 + 根灰）。 */\nexport const FAMILY_PALETTE = ['accent', 'muted', 'alert-soft']\n\n/**\n * 族谱侧栏行序（纯函数，输入 /api/agents 行集）。\n * 行 = {type:'node', id, isRoot, depth, lane, parentLane, join（是否画父连线）,\n *       passThrough:[穿过本行的祖先泳道], family（家族色 index）, row:{...原 agent 数据}}\n *   或 {type:'more', count, kind:'depth'|'siblings', depth, lane}（折叠行「…+n」）。\n * 规则（s6-plan §2）：DFS 子序 = 出生序（输入行序）；深 > maxDepth 折叠后代；\n * 同父 > maxSiblings 折叠多余；lane 列 = 缩进深度；passThrough 供 SVG 竖线延续。\n */\nexport function computeTreeRows(agents, opts = {}) {\n  const { maxDepth = 4, maxSiblings = 6, rootId = ROOT_ID } = opts\n  const list = Array.isArray(agents) ? agents : []\n  const byParent = new Map()\n  for (const a of list) {\n    const key = a.parentId ?? ''\n    if (!byParent.has(key)) byParent.set(key, [])\n    byParent.get(key).push(a)\n  }\n  const descendantCount = (id) => {\n    let n = 0\n    const stack = [id]\n    while (stack.length > 0) {\n      const cur = stack.pop()\n      for (const child of byParent.get(cur) ?? []) { n++; stack.push(child.id) }\n    }\n    return n\n  }\n  const roots = list.filter((a) => (a.parentId ?? null) === null)\n  // 约定根恒先行（其余无父行为防御性并列根）；同层按出生路径 id 自然序（显式声明，\n  // 不依赖输入行序——批 3 项 3）。\n  roots.sort((a, b) => (a.id === rootId ? -1 : b.id === rootId ? 1 : idOrder(a.id, b.id)))\n  const rows = []\n  // 每层记录本层节点的行号，供 passThrough 后处理：有下一兄弟 B 的节点 A，\n  // A.lane 竖线在 (rowA, rowB) 开区间各行的背景继续（父泳道贯穿其子树行）。\n  const walk = (nodes, depth, parentLane, family) => {\n    const lane = depth\n    const total = nodes.length\n    const visible = total > maxSiblings ? nodes.slice(0, maxSiblings - 1) : nodes\n    const levelRowIdx = []\n    visible.forEach((node) => {\n      levelRowIdx.push(rows.length)\n      rows.push({\n        type: 'node',\n        id: node.id,\n        isRoot: (node.parentId ?? null) === null,\n        depth: lane,\n        lane,\n        parentLane,\n        join: parentLane !== null,\n        passThrough: [],\n        family,\n        row: node,\n      })\n      const children = (byParent.get(node.id) ?? []).slice().sort((x, y) => idOrder(x.id, y.id))\n      if (children.length > 0) {\n        if (depth + 1 > maxDepth) {\n          rows.push({ type: 'more', kind: 'depth', count: descendantCount(node.id), depth: lane + 1, lane: lane + 1 })\n        } else {\n          walk(children, depth + 1, lane, family)\n        }\n      }\n    })\n    if (total > visible.length) {\n      const hidden = total - visible.length\n      let hiddenDescendants = 0\n      for (const node of nodes.slice(visible.length)) hiddenDescendants += 1 + descendantCount(node.id)\n      rows.push({ type: 'more', kind: 'siblings', count: hidden, descendants: hiddenDescendants, depth: lane, lane })\n    }\n    // 本层 passThrough 延伸：节点 i 有后继（下一兄弟或折叠 more），lane 背景线贯穿至其后继行前。\n    for (let i = 0; i < levelRowIdx.length; i++) {\n      const hasSuccessor = i + 1 < visible.length || total > visible.length\n      if (!hasSuccessor) continue\n      const rowA = levelRowIdx[i]\n      const rowB = i + 1 < levelRowIdx.length ? levelRowIdx[i + 1] : rows.length // 折叠 more 收尾：延伸到末尾\n      for (let k = rowA + 1; k < rowB; k++) {\n        const r = rows[k]\n        if (r.passThrough !== undefined && !r.passThrough.includes(lane)) r.passThrough.push(lane)\n      }\n    }\n  }\n  walk(roots, 0, null, -1)\n  // 家族色：根的每个直接子树一族一色（顶层支系交替，深层沿用）。\n  let seq = 0\n  for (const r of rows) {\n    if (r.type !== 'node') continue\n    if (r.parentLane === null) r.family = -1 // 根/并列根 = 灰\n    else if (r.depth === 1) r.family = seq++ % 2\n  }\n  return rows\n}\n\n// ---------- 4. 动作可用性（能力数据驱动，无 agent 特判） ----------\n\n/**\n * 头部动作三态（R8）。事实全部来自族谱位置/面板属性，不认 agent id：\n * 根（parentId=null）天然无销毁者 → 毁 off；根面板不跑 LLM/不组装 → 停·缩 off。\n * 返回 {send, interrupt, compact, terminate, model}，值 ∈ 'off'|'ready'|'active'。\n */\nexport function deriveActions(agent) {\n  if (agent === null || agent === undefined) {\n    return { send: 'off', interrupt: 'off', compact: 'off', terminate: 'off', model: 'off' }\n  }\n  const isRoot = (agent.parentId ?? null) === null\n  return {\n    send: isRoot ? 'off' : 'active', // 根非对话窗口（R9）；选中 agent = 对话激活态\n    interrupt: isRoot ? 'off' : 'ready',\n    compact: isRoot ? 'off' : 'ready',\n    terminate: isRoot ? 'off' : 'ready', // 根无祖先 → 销毁权不可达（kernel 同律，UI 只是如实呈现）\n    model: 'ready', // 三环自由：任何节点均可设显式层（家学本体仍只经 config 改）\n  }\n}\n\n// ---------- 5. 流式 live 层（delta = live-only，快照收口不补间隙——三源共识铁律） ----------\n\n/** live 桶容器（agentId → {text, reasoning, tools, startedAt, lastAt}）。 */\nexport function createLiveBuckets() {\n  return Object.create(null)\n}\n\nfunction ensureBucket(buckets, agentId) {\n  let b = buckets[agentId]\n  if (b === undefined) {\n    b = buckets[agentId] = { text: '', reasoning: '', tools: [], startedAt: 0, lastAt: 0 }\n  }\n  return b\n}\n\n/**\n * PilotEvent（SSE JSON 形）→ live 桶就地更新（消费面窄：stream 的 text/reasoning\n * delta + tool 相位；其余事件类型恒穿越无副作用）。收口纪律：轮末快照\n * （letter → loadContext 重建历史）后由调用方 clearBucket——delta 掉了不补，\n * 快照自愈。tool PilotEvent 无 callId → 同名后进先匹配（并行同名=队尾先收口，\n * 已知简化；args 刻意不上广播，chip 只显名字/相位/耗时）。\n */\nexport function applyStreamEvent(buckets, ev) {\n  if (ev === null || typeof ev !== 'object') return buckets\n  const now = Date.now()\n  if (ev.type === 'stream') {\n    const e = ev.event ?? {}\n    if (e.type === 'text-delta' || e.type === 'reasoning-delta') {\n      const b = ensureBucket(buckets, String(ev.agentId))\n      if (b.startedAt === 0) b.startedAt = now\n      if (e.type === 'text-delta') b.text += String(e.text ?? '')\n      else b.reasoning += String(e.text ?? '')\n      b.lastAt = now\n    }\n    return buckets\n  }\n  if (ev.type === 'tool') {\n    const b = ensureBucket(buckets, String(ev.agentId))\n    const name = String(ev.tool ?? '?')\n    const at = Number(ev.at) > 0 ? Number(ev.at) : now\n    if (ev.phase === 'called') {\n      b.tools.push({ name, phase: 'called', at, doneAt: 0 })\n    } else {\n      let matched = false\n      for (let i = b.tools.length - 1; i >= 0; i--) {\n        const t = b.tools[i]\n        if (t.name === name && t.phase === 'called') {\n          t.phase = ev.phase === 'error' ? 'error' : 'success'\n          t.doneAt = at\n          matched = true\n          break\n        }\n      }\n      if (!matched) b.tools.push({ name, phase: ev.phase === 'error' ? 'error' : 'success', at, doneAt: at }) // 断线迟到收口：孤儿 success/error 也上账\n    }\n    b.lastAt = now\n    return buckets\n  }\n  return buckets\n}\n\nexport function clearBucket(buckets, agentId) {\n  delete buckets[agentId]\n}\n\n// ---------- 5b. 出生路径 id 自然序与族谱显式排序 ----------\n\n/** 出生路径 id（`0` / `2` / `1.10`）逐段数值比较（'1.10' > '1.2'，字符串序会错）。 */\nexport function idOrder(a, b) {\n  const pa = String(a).split('.')\n  const pb = String(b).split('.')\n  const n = Math.max(pa.length, pb.length)\n  for (let i = 0; i < n; i++) {\n    const va = i < pa.length ? Number(pa[i]) : -1\n    const vb = i < pb.length ? Number(pb[i]) : -1\n    if (va !== vb) return va - vb\n  }\n  return 0\n}\n\n// ---------- 5c. 二级操作菜单 / 信息面板（数据驱动，无 agent 特判） ----------\n\n/**\n * 树行「⋯」菜单项（批 3 项 4：缩/停/毁从 header 收进本菜单）。state 全由\n * deriveActions 派生（族谱位置事实），督对根 off（面板不跑轮、无 live 流）。\n */\nexport function menuItems(agent) {\n  if (agent === null || agent === undefined) return []\n  const acts = deriveActions(agent)\n  const isRoot = (agent.parentId ?? null) === null\n  const items = [{ key: 'open', label: '对话', state: isRoot ? 'ready' : 'active' }]\n  items.push({ key: 'watch', label: '监督', state: isRoot ? 'off' : 'ready' })\n  if (!isRoot) {\n    items.push({ key: 'interrupt', label: '中断', state: acts.interrupt })\n    items.push({ key: 'compact', label: '压缩', state: acts.compact })\n  }\n  items.push({ key: 'rename', label: '改名', state: 'ready' })\n  items.push({ key: 'instanceCfg', label: '实例配置', state: 'ready' })\n  items.push({ key: 'classCfg', label: '类配置', state: 'ready' })\n  items.push({ key: 'terminate', label: '销毁', state: acts.terminate, danger: true })\n  return items\n}\n\n/** 信息卡/悬浮详情共用的字段行（全名、类、策略、token、最近活跃…）。 */\nexport function infoRows(agent, now = Date.now()) {\n  if (agent === null || agent === undefined) return []\n  const rows = [\n    { k: '全名', v: `${agent.name ?? agent.id}#${agent.id}` },\n    { k: '类', v: String(agent.classRef ?? '—') },\n    { k: '策略', v: String(agent.strategy ?? '—') },\n    { k: '状态', v: `${statusGlyph(agent.status)} ${String(agent.status ?? '')}` },\n    { k: '轮数', v: String(agent.turnCount ?? 0) },\n    { k: '上下文', v: `${Number(agent.ctxTokens ?? 0).toLocaleString()} tokens` },\n    { k: '累计', v: `${Number(agent.totalTokens ?? 0).toLocaleString()} tokens` },\n    { k: '最近活跃', v: Number(agent.lastActive) > 0 ? relativeTime(Number(agent.lastActive), now) : '—' },\n  ]\n  if (agent.model) rows.push({ k: '模型', v: `${String(agent.model)}（${ORIGIN_LABELS[agent.modelOrigin] ?? String(agent.modelOrigin ?? '')}）` })\n  return rows\n}\n\n/**\n * composer 信息条（批 3 布局：header 消失后，当前 agent 关键事实一行横排）。\n * 六项：全名 / 模型 / 策略 / 轮次 / 当前上下文 token / 累计 token。\n */\nexport function composerMeta(agent) {\n  if (agent === null || agent === undefined) return []\n  return [\n    { k: 'agent', v: `${agent.name ?? agent.id}#${agent.id}` },\n    { k: '模型', v: String(agent.model ?? '继承链') },\n    { k: '策略', v: String(agent.strategy ?? '—') },\n    { k: '轮次', v: String(agent.turnCount ?? 0) },\n    { k: '上下文', v: `${Number(agent.ctxTokens ?? 0).toLocaleString()}` },\n    { k: '累计', v: `${Number(agent.totalTokens ?? 0).toLocaleString()}` },\n  ]\n}\n\nconst ORIGIN_LABELS = { explicit: '显式', class: '类基因', inherited: '父继承', home: '家学' }\n\n/** 相对时刻汉字形（禁 emoji 纪律内：纯文字）。 */\nexport function relativeTime(ts, now = Date.now()) {\n  const d = Math.max(0, now - Number(ts))\n  if (Number(ts) <= 0) return '—'\n  if (d < 5000) return '刚刚'\n  if (d < 60000) return `${String(Math.floor(d / 1000))} 秒前`\n  if (d < 3600000) return `${String(Math.floor(d / 60000))} 分前`\n  if (d < 86400000) return `${String(Math.floor(d / 3600000))} 时前`\n  return `${String(Math.floor(d / 86400000))} 天前`\n}\n\n/** 对话尾部统计条原料：token 合计 / 轮数 / 最近一轮耗时（末条 user → 末行）。 */\nexport function turnStats(messages) {\n  const rows = (messages ?? []).filter((m) => m.valid !== false)\n  let tokens = 0\n  let maxTurn = 0\n  let lastUserAt = 0\n  let lastAt = 0\n  let firstAt = 0\n  for (const m of rows) {\n    tokens += Number(m.tokens) || 0\n    maxTurn = Math.max(maxTurn, Number(m.turn) || 0)\n    const at = Number(m.at) || 0\n    if (at > 0) {\n      if (firstAt === 0) firstAt = at\n      lastAt = Math.max(lastAt, at)\n      if (m.role === 'user') lastUserAt = Math.max(lastUserAt, at)\n    }\n  }\n  return { tokens, turns: maxTurn, durationS: lastUserAt > 0 && lastAt > lastUserAt ? (lastAt - lastUserAt) / 1000 : 0, firstAt, lastAt }\n}\n\n// ---------- 6. 思维链折叠视图（dsh 式：running 追最新行，结束定格首行） ----------\n\n/**\n * 思维链文本 → 折叠呈现数据。**full = 原文自然序（流式全文）**，展开态只显\n * full；summary 仅折叠态头部（running = 最新一行，完成 = 首行）——两态零重复。\n * 空 → null 不渲染。\n */\nexport function reasoningView(text, running) {\n  const s = String(text ?? '')\n  if (s.trim() === '') return null\n  const nonEmpty = s.split('\\n').filter((l) => l.trim() !== '')\n  if (nonEmpty.length === 0) return null\n  return {\n    summary: running ? String(nonEmpty[nonEmpty.length - 1]) : String(nonEmpty[0]),\n    full: s,\n  }\n}\n\n// ---------- 7. 上下文占用（进度条）与工具行折叠 ----------\n\n/**\n * 工具结果行 → 折叠呈现数据（**默认折叠**，与思维链默认展开相反——用户裁决）：\n * head = 首行截断摘要 + 规模提示；expanded 态由渲染层给全文。空 → null。\n */\nexport function toolFold(text, max = 72) {\n  const s = String(text ?? '')\n  if (s.trim() === '') return null\n  const first = s.split('\\n', 1)[0] ?? ''\n  const lines = s.split('\\n').length\n  const meta = `${String(s.length).toLocaleString()} 字 · ${String(lines)} 行`\n  return { head: truncate(first, max), meta, full: s }\n}\n\n/** 生效行 token 合计 ÷ 模型窗口上限（valid=false 的 compact 归档行不计）。 */\nexport function contextRatio(messages, window) {\n  const cap = Number(window) > 0 ? Number(window) : 1000000\n  let sum = 0\n  for (const m of messages ?? []) {\n    if (m.valid === false) continue\n    sum += Number(m.tokens) || 0\n  }\n  return Math.min(sum / cap, 1)\n}\n\n/** 三色带：<20% ok（绿）/ 20~40% warn（黄）/ >40% danger（红）。 */\nexport function ratioTone(ratio) {\n  return ratio < 0.2 ? 'ok' : ratio < 0.4 ? 'warn' : 'danger'\n}\n\n// ---------- 8. 极简 markdown 渲染（零依赖；先抽码后转义再结构 = XSS 构造安全） ----------\n\nconst escapeHtml = (s) =>\n  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;')\n\n/** 行内强调/链接（输入已 HTML 转义；占位符 \\u0000I<idx>\\u0000 为纯字母数字不受影响）。 */\nfunction inlineMd(s) {\n  return s\n    .replace(/\\*\\*\\*([^*]+)\\*\\*\\*/g, '<b><i>$1</i></b>')\n    .replace(/\\*\\*([^*]+)\\*\\*/g, '<b>$1</b>')\n    .replace(/(^|[\\s(（])\\*([^*\\n]+)\\*(?=$|[\\s).,!?;:、」』])/, '$1<i>$2</i>') // 单星斜体首处（防乘法噪音，保守只换第一处）\n    .replace(/(^|[\\s(（])_([^_\\n]+)_(?=$|[\\s).,!?;:、」』])/g, '$1<i>$2</i>')\n    .replace(/\\[([^\\]]+)\\]\\((https?:[^)\\s]+|\\/[^)\\s]*)\\)/g, '<a href=\"$2\" target=\"_blank\" rel=\"noopener\">$1</a>')\n}\n\n/**\n * markdown 子集 → HTML（流式容错：未闭合 ``` 视为到文末代码块）。\n * 支持：围栏代码块 / 行内码 / 标题 / 引用 / 无序·有序列表 / 表格（含分隔行）/\n * hr / 粗斜体 / 链接 / 段落（单换行 <br/>）。\n */\nexport function mdToHtml(raw) {\n  const src = String(raw ?? '')\n  if (src.trim() === '') return ''\n  // 1) 抽围栏代码块与行内码为占位符（内容不进转义流水线，还原时各自 escape）。\n  const fences = []\n  const texts = []\n  let text = src\n    .replace(/```([\\s\\S]*?)(?:```|$)/g, (_m, code) => {\n      fences.push(code.replace(/^[^\\n]*\\n/, '').replace(/\\n$/, '')) // 首行语言标忽略\n      return `\\u0000B${fences.length - 1}\\u0000`\n    })\n    .replace(/`([^`\\n]+)`/g, (_m, c) => {\n      texts.push(c)\n      return `\\u0000I${texts.length - 1}\\u0000`\n    })\n  const lines = escapeHtml(text).split('\\n')\n  const out = []\n  let para = []\n  let list = null\n  const flushPara = () => {\n    if (para.length > 0) {\n      out.push('<p>' + para.map(inlineMd).join('<br/>') + '</p>')\n      para = []\n    }\n  }\n  const flushList = () => {\n    if (list !== null) {\n      out.push(`</${list}>`)\n      list = null\n    }\n  }\n  const fenceOnly = (line) => /^\\u0000B(\\d+)\\u0000$/.exec(line.trim())\n  const restoreFence = (m, i) => `<pre><code>${escapeHtml(fences[Number(i)])}</code></pre>`\n  for (let li = 0; li < lines.length; li++) {\n    const line = lines[li]\n    const f = fenceOnly(line)\n    if (f !== null) {\n      flushPara()\n      flushList()\n      out.push(restoreFence('', f[1]))\n      continue\n    }\n    const h = /^(#{1,6})\\s+(.*)$/.exec(line)\n    if (h !== null) {\n      flushPara()\n      flushList()\n      out.push(`<h${String(h[1].length)}>${inlineMd(h[2])}</h${String(h[1].length)}>`)\n      continue\n    }\n    if (/^(-{3,}|\\*{3,}|_{3,})\\s*$/.test(line.trim())) {\n      flushPara()\n      flushList()\n      out.push('<hr/>')\n      continue\n    }\n    const q = /^&gt;\\s?(.*)$/.exec(line)\n    if (q !== null) {\n      flushPara()\n      flushList()\n      out.push(`<blockquote>${inlineMd(q[1])}</blockquote>`)\n      continue\n    }\n    // 表格：| 开头行 + 下一行为分隔行（---|---）触发。\n    if (/^\\s*\\|.*\\|\\s*$/.test(line) && /^\\s*\\|[\\s:|-]+\\|\\s*$/.test(lines[li + 1] ?? '')) {\n      flushPara()\n      flushList()\n      const cells = (row) => row.trim().replace(/^\\||\\|$/g, '').split('|').map((c) => inlineMd(c.trim()))\n      const rows = [cells(line)]\n      li += 1\n      while (li + 1 < lines.length && /^\\s*\\|.*\\|\\s*$/.test(lines[li + 1])) rows.push(cells(lines[++li]))\n      out.push(\n        '<table><thead><tr>' + rows[0].map((c) => `<th>${c}</th>`).join('') + '</tr></thead><tbody>' +\n          rows.slice(1).map((r) => '<tr>' + r.map((c) => `<td>${c}</td>`).join('') + '</tr>').join('') +\n          '</tbody></table>',\n      )\n      continue\n    }\n    const ul = /^\\s*[-*]\\s+(.*)$/.exec(line)\n    const ol = /^\\s*\\d+[.)]\\s+(.*)$/.exec(line)\n    if (ul !== null || ol !== null) {\n      flushPara()\n      const want = ul !== null ? 'ul' : 'ol'\n      if (list !== want) {\n        flushList()\n        out.push(`<${want}>`)\n        list = want\n      }\n      out.push(`<li>${inlineMd(ul !== null ? ul[1] : ol[1])}</li>`)\n      continue\n    }\n    if (line.trim() === '') {\n      flushPara()\n      flushList()\n      continue\n    }\n    para.push(line)\n  }\n  flushPara()\n  flushList()\n  let html = out.join('\\n')\n  html = html.replace(/\\u0000B(\\d+)\\u0000/g, restoreFence) // 行内漏网的围栏占位（如围栏后同行文字）降级为代码块\n  html = html.replace(/\\u0000I(\\d+)\\u0000/g, (_m, i) => `<code>${escapeHtml(texts[Number(i)])}</code>`)\n  return html\n}\n"
}
